let texto = $input.first().json.csv || '';
if (texto.charCodeAt(0) === 0xfeff) texto = texto.slice(1);

function lerCsv(s) {
  const linhas = [];
  let campo = '';
  let linha = [];
  let dentro = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (dentro) {
      if (c === '"') {
        if (s[i + 1] === '"') { campo += '"'; i++; }
        else dentro = false;
      } else campo += c;
    } else {
      if (c === '"') dentro = true;
      else if (c === ',') { linha.push(campo); campo = ''; }
      else if (c === '\r') { /* ignora */ }
      else if (c === '\n') { linha.push(campo); linhas.push(linha); linha = []; campo = ''; }
      else campo += c;
    }
  }
  if (campo !== '' || linha.length) { linha.push(campo); linhas.push(linha); }
  return linhas;
}

const values = lerCsv(texto).filter(l => l.length > 1);
if (values.length < 100) throw new Error('CSV veio incompleto: ' + values.length + ' linhas');

// A planilha e quem sabe o que ja foi ao ar: o publicador escreve
// status, post_id e postado_em nela, nao no CSV. Reescrever a aba a
// partir do repositorio apagaria isso, entao traz de volta por id.
const atual = ($('Planilha: o que ja foi postado').first().json || {}).values || [];
if (atual.length > 1) {
  const ca = atual[0];
  const iId = ca.indexOf('id');
  const guardar = ['status', 'post_id', 'postado_em'];
  const antes = new Map();
  for (let k = 1; k < atual.length; k++) {
    const l = atual[k];
    if (iId >= 0 && l[iId]) antes.set(String(l[iId]), l);
  }
  const cn = values[0];
  const jId = cn.indexOf('id');
  let trazidos = 0;
  for (let k = 1; k < values.length; k++) {
    const l = values[k];
    const v = jId >= 0 ? antes.get(String(l[jId])) : null;
    if (!v) continue;
    for (const col of guardar) {
      const a = ca.indexOf(col);
      const b = cn.indexOf(col);
      if (a >= 0 && b >= 0 && v[a]) { l[b] = v[a]; trazidos++; }
    }
  }
  console.log('valores preservados da planilha:', trazidos);
}

const cab = values[0];
const iTipo = cab.indexOf('tipo');
const feed = values.slice(1).filter(l => l[iTipo] === 'feed').length;

return [{ json: { values, total: values.length - 1, feed, colunas: cab.length } }];

const c = $('Converter CSV').first().json;
const r = $input.first().json || {};
const u = r.updates || {};
return [{ json: {
  linhas_no_csv: c.total,
